    const canSend=MESSAGING_ENABLED&&canType&&!!state.localKey&&keysTrusted&&hasDraft&&!state.uploadingAttachment;
    el.messageInput.disabled=!canType;
    el.messageInput.placeholder=state.selected?.deleted||state.selected?.historyOnly?'This conversation is read-only':!state.selected?'Choose a conversation':state.pendingAttachment?'Add a caption…':!coreReady?'Secure messaging module unavailable':'Write a message…';
    el.sendButton.disabled=!canSend;
    $('attachBtn').disabled=!canType;
    el.sendButton.title=state.selected?.deleted?'This account was deleted; new messages are disabled.':state.selected?.historyOnly?'Restored chat history is read-only.':!coreReady?'Shared ratchet core is unavailable; encrypted sending is disabled.':canSend?'Send encrypted message':!state.localKey?'Encrypted local storage is unavailable':/changed|blocked/i.test(state.peerKeyState||'')?'A recipient-device key changed or is inconsistent; sending is blocked':!keysTrusted?'Recipient-device keys are not ready':'Enter a message to send';
    const headerStatus=state.selected?.deleted?'Archived account · read-only':state.selected?.historyOnly?'Restored history · read-only':!coreReady?'Secure messaging module unavailable':state.peerKeyState?concisePeerState():active?'Encrypted relay connected':'Connecting securely…';
