    if(state.selected)renderChatPresence(state.selected);
    const accountOnline=!!state.user&&active,accountPresence=$('accountPresence'),accountDot=$('accountPresenceDot');if(accountPresence)accountPresence.textContent=accountOnline?'Online':state.user?'Reconnecting…':'Offline';if(accountDot){accountDot.classList.toggle('is-online',accountOnline);accountDot.classList.toggle('is-offline',!!state.user&&!accountOnline);accountDot.setAttribute('aria-label',accountOnline?'Online':state.user?'Reconnecting':'Offline');}
