  function isConversationActivelyViewed(contactId){return !!contactId&&document.visibilityState==='visible'&&document.hasFocus?.()!==false&&state.selected?.id===contactId&&!$('app').classList.contains('hidden')&&!$('conversation').classList.contains('hidden');}
