  function setSessionRestoreNotice(title,message,{retry=false}={}){$('authNoticeTitle').textContent=title;$('authNoticeText').textContent=message;$('restoreSessionRetry').classList.toggle('hidden',!retry);}
  async function restoreSession(){
    if(state.sessionRestoreInProgress)return;
    const retryButton=$('restoreSessionRetry');
    if(!hasSavedSessionHint()){
      retryButton.disabled=false;$('authForm').classList.remove('hidden');$('authTabs').classList.remove('hidden');$('authNotice').classList.add('visible');
      setSessionRestoreNotice(SIGNIN_NOTICE_TITLE,SIGNIN_NOTICE_TEXT);return;
    }
    state.sessionRestoreInProgress=true;sessionCurtain.show();retryButton.disabled=true;
    $('authForm').classList.add('hidden');$('authTabs').classList.add('hidden');$('authNotice').classList.add('visible');
    setSessionRestoreNotice('Restoring your session…','Checking this browser’s saved secure session.');
    let account;
    try{
      account=await window.SereinSessionRestore.fetchAccount(()=>api('/api/v1/me',{cache:'no-store'}),{onRetry:attempt=>setSessionRestoreNotice('Reconnecting to your session…',`The account service did not respond. Retrying (${attempt}/2)…`)});
    }catch(error){
      state.sessionRestoreInProgress=false;retryButton.disabled=false;
      $('authForm').classList.remove('hidden');$('authTabs').classList.remove('hidden');
      if(error?.status===401){forgetSavedSession();setSessionRestoreNotice(SIGNIN_NOTICE_TITLE,SIGNIN_NOTICE_TEXT);}
      else{setSessionRestoreNotice('Could not confirm your saved session','Your session has not been cleared. Check the connection and retry, or sign in again.',{retry:true});}
      sessionCurtain.hide();return;
    }
    state.user=account.user;state.device=account.device;rememberSavedSession();try{localStorage.setItem('serein.stable-device-id.v1',account.device.id);}catch{}state.name=account.user.display_name;state.identity=account.user.username;
    try{await initializeLocalStore();}catch(error){toast(`Local encrypted storage unavailable: ${error.message}`);}
    try{await ensureDeviceKeyEnrollment();}catch(keyError){state.deviceKeyPair=null;state.deviceKeyFingerprint='';toast(`Device key setup is incomplete; encrypted sending is unavailable: ${keyError.message}`);}
    sessionCurtain.show('Preparing Serein','Opening your encrypted local history and checking account data…');await loadAccountSettings();await loadArchivedContacts();await showAccountApp();state.sessionRestoreInProgress=false;retryButton.disabled=false;sessionCurtain.hide();
  }
